const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function patternHTML(data){return `<div class="pattern-grid">${data.pattern.map((x,i)=>`<section class="default-card" data-info-title="${escape(x.title)}"><p class="eyebrow">${String(i+1).padStart(2,'0')} / UNSERE EMPFEHLUNG</p><h3>${escape(x.title)}</h3><p>${escape(x.text)}</p></section>`).join('')}</div>`;}
export function practiceHTML(s){return `<section class="practice-panel" data-info-title="${escape(s.topic)}"><p class="eyebrow">SO WÜRDEN WIR ES MACHEN</p><h4>Das können Sie übernehmen</h4><ol>${s.practice.steps.map(x=>`<li>${escape(x)}</li>`).join('')}</ol><div class="practice-example"><strong>Konkretes Beispiel</strong><p>${escape(s.practice.example)}</p></div><p class="done-check"><strong>Erledigt, wenn:</strong> ${escape(s.practice.done)}</p><p class="git-role"><strong>Git hilft dabei:</strong> ${escape(s.git)}</p></section>`;}
export function comparisonHTML(){return `<div class="demo repo-comparison"><p class="eyebrow">ZWEI ZWECKE · ZWEI ANGEBOTE</p><h4>Für die Studie sinnvoll – für die Publikation anders aufbereitet</h4><div class="table-scroll"><table><thead><tr><th>Im Forschungsrepo</th><th>Warum dort sinnvoll?</th><th>Im Publikationsrepo</th></tr></thead><tbody><tr><th>quellen/tei/rk_1786_b0001.xml</th><td>Übernommene Fassung für den Vergleich mit der Aufbereitung.</td><td>Quellennachweis und Herkunft in Metadaten; kein konkurrierender Korpusordner.</td></tr><tr><th>daten/vereinheitlicht/rk_1786_b0001.xml</th><td>Aufbereiteter Stand für Leas Auswertungen.</td><td>Nach Prüfung der maßgebliche Bestand unter <strong>data/tei/rk_1786_b0001.xml</strong>.</td></tr><tr><th>analysen/reimstudie/eingabe/rk_1786_b0001.xml</th><td>Festgehaltene Eingabe, mit der ein Studienergebnis entstand.</td><td>Die Studie nennt Release und Auswahl. Ihr eingefrorener Ausschnitt wird nicht als zweite Korpusfassung angeboten.</td></tr></tbody></table></div><p>Die Forschungsablage ist für ihren Zweck angemessen. Für die Publikation werden eindeutiger Einstieg, geltende Regeln und ein freigegebener Bestand ergänzt.</p><p><a href="#publikation">Die vollständige empfohlene Publikationsstruktur ansehen ↑</a></p></div>`;}
