export function enrichCards(root,data){
 const patterns=new Map(data.pattern.map(x=>[x.title,x]));
 const effectIndex={'Können andere mit den Daten arbeiten?':1,'Hosting und Verantwortung':0,'Publikationsgrenze und Qualität':2,'Forschungsnachweis und Erhalt':3,'Neue Forschungsschichten':6,'Pflege und Nachfolge':7,'Zugang und Betrieb':4};
 root.querySelectorAll('.flow>section,.use-cases>section,.annotation-ways>section,.care-states>section,.default-card,.effect,.story-takeaway,.repo-map').forEach(card=>{
  if(card.querySelector(':scope > .card-more'))return;
  const heading=card.querySelector('h3,h4,strong');
  const title=card.dataset.infoTitle||heading?.textContent||card.textContent.trim();
  const story=data.stories.find(s=>s.id===(card.closest('.story')?.id||card.closest('[data-story]')?.dataset.story)||s.takeaway.title===title);
  const pattern=patterns.get(title)||data.pattern[effectIndex[title]??1];
  const [example,tip]=extras[title]||(story?[story.practice.example,story.practice.steps[0]]:[pattern.example,pattern.tip]);
  const detail=document.createElement('details');detail.className='card-more';detail.innerHTML=`<summary aria-label="${escape(title)}: Beispiel und Tipp">Beispiel &amp; Tipp <span aria-hidden="true">＋</span></summary><div><p><strong>Beispiel:</strong> ${escape(example)}</p><p><strong>Tipp:</strong> ${escape(tip)}</p></div>`;card.append(detail);
 });
}
